(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.03-t*0.5)*8 + Math.cos(mx*0.025+t*0.4)*6;
  const w2y = Math.cos(mx*0.028+t*0.45)*8 + Math.sin(my*0.022-t*0.35)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.3+4)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.45+2)*70, 220+Math.sin(t*0.65+1)*40, 0.085, 1.8, 1.15]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,amp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*amp;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    hS += Math.sin(d*f*0.5+t*sp*0.3+3.0)*amp*0.5;
  }
  const n=src.length, act=aS/n, inh=iS/n, harm=hS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3
    +Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15
    +Math.sin(sx*0.08+t*1.8)*Math.sin(sy*0.06-t*1.3)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35
    +Math.sin(dist*0.07-ang*5+t*0.8)*0.15;
  const micro = (Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)+Math.sin((sx-sy)*0.2+t*2)*Math.sin((sx+sy)*0.18-t*1.5))*0.15;
  const reaction = Math.tanh((act-inh*0.65+harm*0.3+bg*0.25+spiral+micro)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const pulse = 1.0+Math.sin(t*0.8)*0.05;
  const v = (reaction*0.65+cell*0.2+micro*0.15)*pulse*0.5+0.5;
  const pal = [[5,12,55],[12,50,95],[18,95,125],[25,150,135],[180,185,60],[230,160,50],[200,90,60],[150,45,65],[85,22,60],[40,15,55],[5,12,55]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const gf=f*f*(3-2*f);
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.05:0.95;
  const hl=Math.max(0,reaction-0.6)*0.4;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*gf)*lum*edge+hl*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*gf)*lum*edge+hl*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*gf)*lum*edge+hl*20)|0)
  ];
}
